from pysat.solvers import Glucose3
from pysat.card import CardEnc

# We have 5 rows (0..4) and 5 columns (0..4)
# Variable mapping: var = row*5 + col + 1 (1-indexed for pysat)
n = 5

def var(r, c):
    return r * n + c + 1

solver = Glucose3()

# Each row must have exactly one queen
for r in range(n):
    clause = [var(r, c) for c in range(n)]
    solver.add_clause(clause)
    # At most one per row
    for c1 in range(n):
        for c2 in range(c1+1, n):
            solver.add_clause([-var(r, c1), -var(r, c2)])

# Each column must have at most one queen
for c in range(n):
    for r1 in range(n):
        for r2 in range(r1+1, n):
            solver.add_clause([-var(r1, c), -var(r2, c)])

# Diagonals (top-left to bottom-right): r-c constant
for diff in range(-n+1, n):
    cells = [(r, c) for r in range(n) for c in range(n) if r - c == diff]
    for i in range(len(cells)):
        for j in range(i+1, len(cells)):
            r1, c1 = cells[i]
            r2, c2 = cells[j]
            solver.add_clause([-var(r1, c1), -var(r2, c2)])

# Diagonals (top-right to bottom-left): r+c constant
for s in range(0, 2*n-1):
    cells = [(r, c) for r in range(n) for c in range(n) if r + c == s]
    for i in range(len(cells)):
        for j in range(i+1, len(cells)):
            r1, c1 = cells[i]
            r2, c2 = cells[j]
            solver.add_clause([-var(r1, c1), -var(r2, c2)])

# Fixed assignment: q[1] = 2 (row 1, column 2)
solver.add_clause([var(1, 2)])

if solver.solve():
    model = solver.get_model()
    solution = []
    for r in range(n):
        for c in range(n):
            if model[var(r, c)-1] > 0:
                solution.append(c)
    print("SAT, solution:", solution)
else:
    print("UNSAT")
